package writer

import "github.com/PorticoMediaServer/portico/server/internal/store/stmt"

func mpSessionDomainDefinitions() []stmt.Definition {
	d := append(mpPrepCommonDefinitions(), mpQueueSessionCompositionDefinitions()...)
	specs := []struct {
		id, sql, types string
		kind           stmt.Kind
	}{
		{"mp.session.physical", `SELECT id,mp_command_incarnation,mp_revision,generation,mp_execution_id,request_id,item_id,asset_id,state,mode,grant_hash,grant_token,expires_at,CASE WHEN mp_retired_generation=generation THEN 1 ELSE 0 END,CASE WHEN mp_exited_generation=generation AND mp_exit_request_id=mp_retire_request_id AND length(mp_exit_supervisor_incarnation)=16 AND mp_exited_ms>0 THEN 1 ELSE 0 END,mp_cleanup_complete,mp_exit_digest,mp_cleanup_cursor,mp_grant_retired,coalesce((SELECT bytes FROM playback_hls_reservations WHERE session_id=playback_sessions.id),0),mp_retired_generation,mp_exited_generation,mp_retire_request_id,mp_exit_supervisor_incarnation,mp_exited_ms,mp_exit_request_id,mp_delivery_ready FROM playback_sessions WHERE id=?`, "s", stmt.Read},
		{"mp.session.item_identity", `SELECT 1 FROM catalog_entities WHERE id=? AND public_id=?`, "ib", stmt.Read},
		{"mp.session.logical", `SELECT id,mp_command_incarnation,revision,generation,mp_presentation_generation,media_session_id,media_generation,state,position_ms,start_position_ms,last_seq,lease_expires_ms,ended_ms,end_reason,mp_engine,mp_presentation_url,item_id,part_index,version_id,queue_id,entry_id,(SELECT item_public_id FROM mp_media_inputs WHERE media_session_id=playback_v1_sessions.media_session_id) FROM playback_v1_sessions WHERE id=?`, "s", stmt.Read},
		{"mp.session.input_current", `SELECT 1 FROM mp_media_inputs WHERE media_session_id=? AND server_id=? AND authority=? AND account_id=? AND profile_id=? AND device_id=? AND family_id=? AND library_id=? AND library_source_id=? AND asset_id=? AND inventory_object_id=? AND inventory_revision=? AND root_identity=? AND incarnation=? AND remote_source_id=? AND effective_configuration=? AND read_policy_witness=? AND read_authority_witness=? AND library_generation=? AND raw_configuration_generation=? AND profile_revision=? AND size=? AND modified_ns=? AND queue_id=? AND queue_entry_id=? AND queue_owner_kind=? AND queue_owner_id=? AND queue_revision=? AND queue_custody_generation=? AND part_index=?`, "ssssssssssssssssssiiiiissssiii", stmt.Read},
		{"mp.session.accepted_preparation", `SELECT 1 FROM playback_start_preparations AS p CROSS JOIN playback_start_preparation_lifecycle AS l ON l.operation_id=p.id CROSS JOIN playback_start_preparation_results AS r ON r.operation_id=p.id CROSS JOIN mp_start_execution AS x ON x.operation_id=p.id AND x.execution_id=l.execution_id WHERE p.id=? AND l.revision=? AND l.state='accepted' AND l.sealed=1 AND r.session_id=? AND r.legacy_session_id=? AND p.asset_id=? AND p.device_id=? AND p.mp_birth_id=? AND l.execution_id=? AND length(x.result_digest)=64 AND r.legacy_generation=? AND x.cleaned=0 AND x.custody_media_session_id=''`, "sissssbsi", stmt.Read},
		{"mp.session.preparation_transfer", `UPDATE mp_start_execution SET custody_media_session_id=? WHERE operation_id=? AND execution_id=? AND cleaned=0 AND custody_media_session_id='' RETURNING 1`, "sss", stmt.Write},
		{"mp.session.physical_insert", `INSERT INTO playback_sessions(id,session_hash,account_id,profile_id,item_id,asset_id,generation,state,grant_hash,grant_token,expires_at,request_id,duration,mode,mp_command_incarnation,mp_revision,mp_execution_id,mp_cleanup_complete,mp_exit_digest,mp_cleanup_cursor,mp_grant_retired,mp_birth_id,mp_start_birth_id) VALUES(?,?,?,?,?,?,?,'preparing',?,?,?,?,?/1000.0,?,?,1,?,0,'',0,0,?,?) RETURNING 1`, "ssssisissssisbsbb", stmt.Write},
		{"mp.session.input_insert", `INSERT INTO mp_media_inputs(media_session_id,server_id,authority,account_id,profile_id,device_id,family_id,grant_id,session_hash,epoch,token_generation,original_horizon_ms,library_id,library_source_id,asset_id,inventory_object_id,inventory_revision,root_identity,incarnation,remote_source_id,effective_configuration,read_policy_witness,read_authority_witness,library_generation,raw_configuration_generation,profile_revision,size,modified_ns,queue_id,queue_entry_id,queue_owner_kind,queue_owner_id,queue_revision,queue_custody_generation,part_index,item_public_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING 1`, "sssssssssiiisssssssssssiiiiissssiiib", stmt.Write},
		{"mp.session.logical_insert", `INSERT INTO playback_v1_sessions(id,device_id,account_id,profile_id,authority,start_key,start_digest,kind,role,state,item_id,version_id,part_index,queue_id,entry_id,request,revision,generation,media_session_id,media_generation,presentation,start_position_ms,position_ms,lease_expires_ms,created_ms,updated_ms,mp_command_incarnation,mp_presentation_generation,mp_engine,mp_presentation_url,mp_desired_state,mp_birth_id,mp_start_birth_id) VALUES(?,?,?,?,?,?,?,'vod','player','preparing',?,?,?,?,?,'',1,1,?,?,'',?,?,?,?,?,?,1,?,?,?,?,?) RETURNING 1`, "sssssssisisssiiiiiibsssbb", stmt.Write},
		{"mp.session.source_insert", `INSERT INTO playback_source_pins(session_id,asset_id,size,modified_ns,binding,source_id,inventory_object_id,root,root_identity,relative_path,object_identity,follow_symlinks) SELECT ?,a.token,a.size,a.modified_ns,'inventory',s.id,o.id,s.root,s.root_identity,o.relative_path,o.object_identity,s.follow_symlinks FROM catalog_assets AS a CROSS JOIN inventory_objects AS o ON o.asset_id=a.token CROSS JOIN library_sources AS s ON s.id=o.source_id WHERE a.token=? AND a.size=? AND a.modified_ns=? AND s.id=? AND o.id=? AND s.root_identity=? AND s.incarnation=? AND o.root_incarnation=s.incarnation AND o.retired=0 AND a.available=1 AND s.enabled=1 RETURNING 1`, "ssiissss", stmt.Write},
		{"mp.session.physical_source_insert", `INSERT INTO playback_physical_source_pins(session_id,source_id,incarnation,configuration_generation) VALUES(?,?,?,?) RETURNING 1`, "sssi", stmt.Write},
		{"mp.session.ready", `UPDATE playback_v1_sessions SET state=mp_desired_state,revision=revision+1,updated_ms=?,paused_since_ms=CASE WHEN mp_desired_state='paused' THEN ? ELSE 0 END WHERE id=? AND revision=? AND media_session_id=? AND media_generation=? AND state='preparing' AND ended_ms=0 AND EXISTS(SELECT 1 FROM playback_sessions AS p WHERE p.id=playback_v1_sessions.media_session_id AND p.mp_execution_id=? AND p.mp_delivery_ready=1 AND p.mp_retired_generation<p.generation AND p.mp_exited_generation<p.generation) RETURNING state`, "iisisis", stmt.Write},
		{"mp.session.pause", `UPDATE playback_v1_sessions SET state='paused',last_seq=?,paused_since_ms=?,revision=revision+1,updated_ms=? WHERE id=? AND revision=? AND generation=? AND last_seq=? AND ended_ms=0 AND state IN('playing','paused') RETURNING 1`, "iiisiii", stmt.Write},
		{"mp.session.resume", `UPDATE playback_v1_sessions SET state='playing',last_seq=?,paused_since_ms=0,revision=revision+1,updated_ms=? WHERE id=? AND revision=? AND generation=? AND last_seq=? AND ended_ms=0 AND state IN('playing','paused') RETURNING 1`, "iisiii", stmt.Write},
		{"mp.session.seek", `UPDATE playback_v1_sessions SET position_ms=?,last_seq=?,revision=revision+1,updated_ms=? WHERE id=? AND revision=? AND generation=? AND last_seq=? AND ended_ms=0 AND state IN('playing','paused') AND ?<=(SELECT duration*1000.0 FROM playback_sessions WHERE id=?) RETURNING 1`, "iiisiiiis", stmt.Write},
		{"mp.session.renew", `UPDATE playback_v1_sessions SET lease_expires_ms=?,revision=revision+1,updated_ms=? WHERE id=? AND revision=? AND generation=? AND lease_expires_ms=? AND ended_ms=0 RETURNING 1`, "iisiii", stmt.Write},
		{"mp.session.request_stop", `UPDATE playback_sessions SET state='stopped',mp_grant_retired=1,mp_retired_generation=generation,mp_retire_request_id=?,mp_revision=mp_revision+1 WHERE id=? AND mp_revision=? AND generation=? AND mp_execution_id=? AND mp_retired_generation<generation AND mp_exited_generation<generation RETURNING 1`, "ssiis", stmt.Write},
		{"mp.session.stop", `UPDATE playback_v1_sessions SET state='stopped',ended_ms=?,end_reason=?,revision=revision+1,updated_ms=? WHERE id=? AND revision=? AND generation=? AND media_session_id=? AND media_generation=? AND ended_ms=0 RETURNING 1`, "isisiisi", stmt.Write},
		{"mp.session.exit", `UPDATE playback_sessions SET mp_exited_generation=generation,mp_exit_supervisor_incarnation=?,mp_exited_ms=?,mp_exit_request_id=?,mp_exit_digest=?,mp_cleanup_cursor=?,mp_cleanup_complete=?,mp_revision=mp_revision+1 WHERE id=? AND mp_revision=? AND generation=? AND mp_execution_id=? AND mp_cleanup_cursor=? AND mp_retired_generation=generation AND mp_retire_request_id=? AND mp_cleanup_complete=0 AND (mp_exited_generation<generation OR (mp_exit_supervisor_incarnation=? AND mp_exited_ms=? AND mp_exit_request_id=? AND mp_exit_digest=?)) RETURNING 1`, "bissiisiisisbiss", stmt.Write},
		{"mp.session.reconcile_revision", `UPDATE playback_v1_sessions SET revision=revision+1,updated_ms=? WHERE id=? AND revision=? AND generation=? RETURNING 1`, "isii", stmt.Write},
		{"mp.session.cleanup_empty", `SELECT 1 FROM playback_sessions AS p WHERE p.id=? AND NOT EXISTS(SELECT 1 FROM playback_source_pins WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM playback_physical_source_pins WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM prepared_media_session_pins WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM playback_subtitle_pins WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM playback_disc_pins WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM playback_private_presentations WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM mp_media_read_pins WHERE media_session_id=p.id) AND NOT EXISTS(SELECT 1 FROM mp_remote_delivery_inputs WHERE media_session_id=p.id) AND NOT EXISTS(SELECT 1 FROM subtitle_remote_sessions WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM mp_direct_delivery WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM playback_hls_reservations WHERE session_id=p.id) AND NOT EXISTS(SELECT 1 FROM mp_hls_window_custody WHERE session_id=p.id AND cleaned=0)`, "s", stmt.Read},
	}
	specs = append(specs, []struct {
		id, sql, types string
		kind           stmt.Kind
	}{
		{"mp.session.replace_begin", `INSERT INTO mp_session_replacements(session_id,old_media_id,old_media_generation,old_logical_generation,old_execution_id,new_media_id,new_execution_id,new_media_incarnation,input_digest,phase) VALUES(?,?,?,?,?,?,?,?,?,'requested') ON CONFLICT(session_id) DO UPDATE SET old_media_id=excluded.old_media_id,old_media_generation=excluded.old_media_generation,old_logical_generation=excluded.old_logical_generation,old_execution_id=excluded.old_execution_id,new_media_id=excluded.new_media_id,new_execution_id=excluded.new_execution_id,new_media_incarnation=excluded.new_media_incarnation,input_digest=excluded.input_digest,phase='requested' WHERE mp_session_replacements.phase='installed' AND mp_session_replacements.old_logical_generation<excluded.old_logical_generation RETURNING 1`, "ssiisssbb", stmt.Write},
		{"mp.session.replace_current", `SELECT 1 FROM mp_session_replacements WHERE session_id=? AND old_media_id=? AND old_media_generation=? AND old_logical_generation=? AND old_execution_id=? AND new_media_id=? AND new_execution_id=? AND new_media_incarnation=? AND input_digest=? AND phase='requested'`, "ssiisssbb", stmt.Read},
		{"mp.session.replace_preparing", `UPDATE playback_v1_sessions SET state='preparing',revision=revision+1,updated_ms=? WHERE id=? AND revision=? AND generation=? AND ended_ms=0 RETURNING 1`, "isii", stmt.Write},
		{"mp.session.birth_binding", `SELECT mp_birth_id,mp_start_birth_id FROM playback_v1_sessions WHERE id=?`, "s", stmt.Read},
		{"mp.session.replace_finish", `UPDATE playback_v1_sessions SET media_session_id=?,media_generation=?,item_id=?,version_id=?,part_index=?,queue_id=?,entry_id=?,position_ms=?,start_position_ms=?,lease_expires_ms=?,mp_engine=?,mp_presentation_url=?,mp_desired_state=?,updated_ms=?,revision=revision+1,generation=generation+1,mp_presentation_generation=mp_presentation_generation+1 WHERE id=? AND revision=? AND generation=? AND media_session_id=? AND media_generation=? AND ended_ms=0 AND state='preparing' RETURNING 1`, "siisissiiisssisiisi", stmt.Write},
		{"mp.session.replace_installed", `UPDATE mp_session_replacements SET phase='installed' WHERE session_id=? AND old_media_id=? AND old_logical_generation=? AND input_digest=? AND phase='requested' RETURNING 1`, "ssib", stmt.Write},
	}...)

	for _, s := range specs {
		v := mpPrepDefinition(s.id, s.sql, s.types, s.kind)
		v.CallSites = []string{"store/writer/mp_session_domain.go", "store/writer/mp_source_pins.go", "store/writer/mp_hls_domain.go"}
		if s.id == "mp.session.physical_insert" {
			v.Params[15].Nullable = true
			v.Params[16].Nullable = true
		}
		if s.id == "mp.session.logical_insert" {
			v.Params[23].Nullable = true
			v.Params[24].Nullable = true
		}
		d = append(d, v)
	}
	return d
}
